        for k,v in config['global'].items():
            if normalize_opt_name(k)=='database' and isinstance(v,str):
                db_from_config=v
                break
    if db_from_config:
        return db_from_config, None
    if env_db:
        return env_db, None
    home=os.environ.get('HOME','')
    xdg=os.environ.get('XDG_CACHE_HOME','')
    old_path=os.path.join(home,'.duc.db') if home else ''
    if xdg:
        new_path=os.path.join(xdg,'duc','duc.db')
    else:
        new_path=os.path.join(home,'.cache','duc','duc.db') if home else ''
    if old_path and os.path.isfile(old_path):
        warning=f'Using old database at "{old_path}", please move this to "$XDG_CACHE_HOME/duc/duc.db"'
        return old_path, warning
    if new_path:
        return new_path, None
    if old_path:
        return old_path, None
