def get_dir_node(conn, dev, ino):
    key=f"{dev}/{ino:x}"
    cur=conn.cursor()
    cur.execute("SELECT value FROM blobs WHERE key=?",(key,))
    row=cur.fetchone()
    if not row:
        return None
    try:
        return json.loads(row[0].decode())
    except:
        return None

def get_root_node(conn, path):
    cur=conn.cursor()
    cur.execute("SELECT value FROM blobs WHERE key=?",(path,))
    row=cur.fetchone()
    if not row:
        return None
    try:
        return json.loads(row[0].decode())
    except:
        return None

def resolve_path(conn, requested_path):
    cur=conn.cursor()
    cur.execute("SELECT value FROM blobs WHERE key='duc_index_reports'")
    row=cur.fetchone()
    if not row:
        return None, None
    try:
        reports=json.loads(row[0].decode())
    except:
        return None, None
    requested_path=os.path.abspath(requested_path)
    best=None
    best_len=-1
    for rep in reports:
        rpath=rep['path']
        if requested_path==rpath or requested_path.startswith(rpath+'/'):
            if len(rpath)>best_len:
                best=rep
                best_len=len(rpath)
    if not best:
        return None, None
    root_info=get_root_node(conn, best['path'])
    if not root_info:
        return None, None
    if requested_path==best['path']:
        dir_node=get_dir_node(conn, root_info['dev'], root_info['ino'])
        if dir_node:
            return dir_node, root_info
        return None, root_info
    rel=os.path.relpath(requested_path, best['path'])
    parts=rel.split('/')
    cur_dev=root_info['dev']
    cur_ino=root_info['ino']
    cur_node=get_dir_node(conn, cur_dev, cur_ino)
    if not cur_node:
        return None, None
    for part in parts:
        found=None
        for ent in cur_node.get('entries',[]):
            if ent['name']==part and ent.get('is_dir'):
                found=ent
                break
        if not found:
            return None, None
        child=get_dir_node(conn, found['dev'], found['ino'])
        if not child:
            return None, None
        cur_node=child
    return cur_node, root_info

def info_command(positional, opts, config):
    cli_db=opts.get('database')
    env_db=os.environ.get('DUC_DATABASE')
    db_path, warning=get_db_path('info', cli_db, config, env_db)
    if warning:
        eprint(warning)
    conn, err=open_db(db_path)
    if err=="not_found":
        eprint(f"Error opening: {db_path} - Database not found")
        eprint("Database not found")
        sys.exit(0)
    elif err=="corrupt":
        eprint(f"Error opening: {db_path} - Database corrupt and not usable")
        eprint("Database corrupt and not usable")
        sys.exit(0)
    if opts.get('debug') or opts.get('verbose'):
        print(f'Reading from database "{db_path}"')
    cur=conn.cursor()
    cur.execute("SELECT value FROM blobs WHERE key='duc_index_reports'")
    row=cur.fetchone()
    if not row:
        print("No database info found")
        return
    try:
        reports=json.loads(row[0].decode())
    except:
        eprint(f"Error opening: {db_path} - Database corrupt and not usable")
        eprint("Database corrupt and not usable")
        sys.exit(0)
    apparent=opts.get('apparent', False)
    bytes_flag=opts.get('bytes', False)
    hist_flag=opts.get('histogram', False)
    print(f"{'Date':<10} {'Time':<10} {'Files':>8} {'Dirs':>8} {'Size':>8} Path")
    for rep in reports:
        ts=rep.get('time', time.time())
        date_str=time.strftime("%Y-%m-%d", time.localtime(ts))
        time_str=time.strftime("%H:%M:%S", time.localtime(ts))
        files=rep.get('files',0)
        dirs=rep.get('dirs',0)
        size=rep.get('size_apparent',0) if apparent else rep.get('size_actual',0)
        size_str=str(size) if bytes_flag else human_size(size)
        print(f"{date_str} {time_str} {files:8} {dirs:8} {size_str:>8} {rep.get('path','')}")
        if hist_flag:
            print("")
            print("Histogram:")
            print("----------")
            cur.execute("SELECT value FROM blobs WHERE key='duc_index_histograms'")
            row2=cur.fetchone()
            if row2:
                try:
                    hists=json.loads(row2[0].decode())
                    he=hists.get(rep.get('path'))
                    if he:
                        hist=he.get('hist_apparent' if apparent else 'hist_actual', [])
                        for i,cnt in enumerate(hist):
                            if cnt!=0:
                                print(f"2^{i}   {cnt}")
                except:
                    pass
    conn.close()

