                            eprint("Try 'duc --help' for more information.")
                            sys.exit(1)
                else:
                    opt_name=a[2:]
                    found=False
                    for dest,(short,has_val,long_opts) in allowed.items():
                        if opt_name in long_opts:
                            found=True
                            if has_val:
                                if i+1 < len(cmd_args) and not cmd_args[i+1].startswith('-'):
                                    parsed[dest]=cmd_args[i+1]
                                    i+=1
                                else:
                                    parsed[dest]=None
                            else:
                                parsed[dest]=True
                            break
                    if not found:
                        if opt_name in ('debug','verbose','quiet'):
                            parsed[opt_name]=True
                        else:
                            eprint(f"{sys.argv[0]}: invalid option -- '{opt_name}'")
                            eprint("Try 'duc --help' for more information.")
                            sys.exit(1)
            elif a.startswith('-') and len(a)>1:
                chars=a[1:]
                j=0
                while j < len(chars):
                    ch=chars[j]
                    found=False
                    for dest,(short,has_val,long_opts) in allowed.items():
                        if short==ch:
                            found=True
                            if has_val:
                                if j+1 < len(chars):
                                    parsed[dest]=chars[j+1:]
                                    j=len(chars)
                                else:
                                    if i+1 < len(cmd_args) and not cmd_args[i+1].startswith('-'):
                                        parsed[dest]=cmd_args[i+1]
                                        i+=1
                                    else:
                                        parsed[dest]=None
