                            eprint("Try 'duc --help' for more information.")
                            sys.exit(1)
                    j+=1
            else:
                positional.append(a)
            i+=1
        return parsed, positional

    parsed_opts, positional = parse_opts()
    # merge config
    for dest,(short,has_val,long_opts) in allowed.items():
        if dest in parsed_opts:
            continue
        for sec_name in [subcmd,'global']:
            if sec_name in config:
                sec=config[sec_name]
                for cfg_opt,cfg_val in sec.items():
                    norm=normalize_opt_name(cfg_opt)
